WITH a AS (
  SELECT ST_PointOnSurface(geom) AS p FROM residential_areas WHERE name='百水芊城' ORDER BY id LIMIT 1
), b AS (
  SELECT geom AS p FROM metro_stations WHERE name='马群' LIMIT 1
), sv AS (
  SELECT (SELECT id FROM walk_vertices WHERE in_main ORDER BY geom <-> (SELECT p FROM a) LIMIT 1) AS s,
         (SELECT id FROM walk_vertices WHERE in_main ORDER BY geom <-> (SELECT p FROM b) LIMIT 1) AS t
)
SELECT s, t, agg_cost AS meters
FROM sv, LATERAL pgr_dijkstra('SELECT id, source, target, cost_m AS cost, cost_m AS reverse_cost FROM walk_edges', s, t, directed => false)
ORDER BY agg_cost DESC LIMIT 1;

