WITH ra AS (
  SELECT id, name, ST_PointOnSurface(geom) AS pt FROM residential_areas WHERE name='锁金四村' ORDER BY id LIMIT 1
), sv AS (
  SELECT v.id, v.geom FROM ra, walk_vertices v WHERE v.in_main ORDER BY v.geom <-> ra.pt LIMIT 1
), dd AS (
  SELECT * FROM pgr_drivingDistance('SELECT id, source, target, cost_m AS cost, cost_m AS reverse_cost FROM walk_edges', (SELECT id FROM sv), 500, directed => false)
), reach AS (
  SELECT node AS vid, agg_cost FROM dd
), schools AS (
  SELECT p.id, p.name, ST_PointOnSurface(p.geom) AS pt FROM pois p WHERE p.subtype='school' AND p.name LIKE '%小学%'
), snapped AS (
  SELECT s.id, s.name, (SELECT v.id FROM walk_vertices v WHERE v.in_main ORDER BY v.geom <-> s.pt LIMIT 1) AS vid
  FROM schools s
)
SELECT sn.name, r.agg_cost AS network_m
FROM snapped sn JOIN reach r ON r.vid = sn.vid
ORDER BY r.agg_cost;

