WITH ra AS (
  SELECT id, name, ST_PointOnSurface(geom) AS pt FROM residential_areas WHERE name='香格里拉花园' ORDER BY id LIMIT 1
), sv AS (
  SELECT v.id, v.geom FROM walk_vertices v, ra WHERE v.in_main ORDER BY v.geom <-> ra.pt LIMIT 1
), kg AS (
  SELECT p.id, p.name, p.geom FROM pois p WHERE p.subtype='kindergarten'
), kgv AS (
  SELECT kg.id, kg.name, (SELECT v.id FROM walk_vertices v WHERE v.in_main ORDER BY v.geom <-> kg.geom LIMIT 1) AS vid FROM kg
), dd AS (
  SELECT * FROM pgr_drivingDistance('SELECT id, source, target, cost_m AS cost, cost_m AS reverse_cost FROM walk_edges', (SELECT id FROM sv), 300, directed => false)
)
SELECT (SELECT count(*) FROM dd d JOIN kgv k ON k.vid=d.node) AS reachable_kindergartens,
       (SELECT string_agg(DISTINCT k.name, ', ') FROM dd d JOIN kgv k ON k.vid=d.node) AS names,
       (SELECT min(d.agg_cost) FROM dd d JOIN kgv k ON k.vid=d.node) AS min_cost_m

