WITH ra AS (
  SELECT id, name, ST_PointOnSurface(geom) AS pt FROM residential_areas WHERE name='香格里拉花园' ORDER BY id LIMIT 1
), sv AS (
  SELECT v.id, v.geom FROM walk_vertices v, ra WHERE v.in_main ORDER BY v.geom <-> ra.pt LIMIT 1
), kg AS (
  SELECT p.id, p.name, p.geom, ST_Distance(p.geom::geography, ra.pt::geography) AS straight_m
  FROM pois p, ra WHERE p.subtype='kindergarten' AND ST_DWithin(p.geom::geography, ra.pt::geography, 1500)
), kgv AS (
  SELECT kg.*, (SELECT v.id FROM walk_vertices v WHERE v.in_main ORDER BY v.geom <-> kg.geom LIMIT 1) AS vid FROM kg
), dd AS (
