)
SELECT k.name, round(k.straight_m) AS straight_m, round(min(d.agg_cost)) AS network_m
FROM kgv k LEFT JOIN dd d ON d.node=k.vid
GROUP BY k.name, k.straight_m ORDER BY network_m NULLS LAST LIMIT 5

