       (SELECT min(agg_cost) FROM pgr_dijkstra('SELECT id, source, target, cost_m AS cost, cost_m AS reverse_cost FROM walk_edges', (SELECT vid FROM snap), st.vid, directed => false)) AS net_dist_m
FROM snap r, st
WHERE st.vid IN (SELECT node FROM reach)
ORDER BY net_dist_m
LIMIT 10;

