WITH ra AS (
  SELECT id, name, ST_PointOnSurface(geom) AS pt FROM residential_areas WHERE name = '莲花新城南苑' ORDER BY id LIMIT 1
), sv AS (
  SELECT v.id, v.geom FROM ra, LATERAL (SELECT id, geom FROM walk_vertices WHERE in_main ORDER BY geom <-> ra.pt LIMIT 1) v
), pol AS (
  SELECT p.id, p.name, p.geom FROM pois p WHERE p.subtype = 'police'
), pv AS (
  SELECT pol.id, pol.name, (SELECT v.id FROM walk_vertices v WHERE v.in_main ORDER BY v.geom <-> pol.geom LIMIT 1) AS vid FROM pol
), dd AS (
  SELECT * FROM pgr_drivingDistance('SELECT id, source, target, cost_m AS cost, cost_m AS reverse_cost FROM walk_edges', (SELECT id FROM sv), 800, directed => false)
)
SELECT ra.name AS area, (SELECT count(*) FROM pv JOIN dd ON dd.node = pv.vid) > 0 AS compliant,
       'GB50180-2018:C.0.1:派出所' AS clause_id, 800 AS radius_m,
       (SELECT min(dd.agg_cost) FROM pv JOIN dd ON dd.node = pv.vid) AS nearest_police_m,
       (SELECT string_agg(DISTINCT pv.name, ', ') FROM pv JOIN dd ON dd.node = pv.vid) AS police_names
FROM ra

